function evalSteps(params, inputs, t) {
  /* why: a numpty sequencer any signal can play - words and images
     drive the melody, the melody drives a voice. */
  var stepsN = Math.max(2, Math.round(params.steps));
  var pos = t * params.tempo / 3600;
  var prev = (t - 1) * params.tempo / 3600;
  var idx = Math.floor(pos) % stepsN;
  var scale = [0, 3, 5, 7, 10];
  var k = idx * 3 + Math.floor(params.mod * 12);
  var note = params.root + scale[k % scale.length] + 12 * (Math.floor(k / scale.length) % 2);
  var trig = (t <= 0 || Math.floor(pos) !== Math.floor(prev)) ? 1 : 0;
  return { note: note, trig: trig, step: idx };
}
